import{_ as a,o as s,c as i,a3 as e}from"./chunks/framework.qCVWde4n.js";const k=JSON.parse('{"title":"调试与日志接口","description":"","frontmatter":{},"headers":[],"relativePath":"dev/logging-api.md","filePath":"dev/logging-api.md","lastUpdated":null}'),d={name:"dev/logging-api.md"};function r(o,t,l,n,h,p){return s(),i("div",null,[...t[0]||(t[0]=[e(`<h1 id="调试与日志接口" tabindex="-1">调试与日志接口 <a class="header-anchor" href="#调试与日志接口" aria-label="Permalink to &quot;调试与日志接口&quot;">​</a></h1><p>真机上出了问题，你连不上电脑——所以框架的日志系统是<strong>为「远程自助诊断」设计的</strong>。这一页讲怎么用。</p><h2 id="为什么日志必须落盘" tabindex="-1">为什么日志必须落盘 <a class="header-anchor" href="#为什么日志必须落盘" aria-label="Permalink to &quot;为什么日志必须落盘&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">只存内存的日志等于没有日志</p><p>游戏一关，内存日志就丢了。真机远程诊断拿不到任何证据。</p><p>所以框架把日志<strong>同时写到文件</strong>：<code>&lt;ModRoot&gt;/AFMOD_log.txt</code>。玩家「复制全部日志」一键导出，整段发给作者即可。</p></div><h2 id="落盘策略-为什么这么设计" tabindex="-1">落盘策略（为什么这么设计） <a class="header-anchor" href="#落盘策略-为什么这么设计" aria-label="Permalink to &quot;落盘策略（为什么这么设计）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>机制</th><th>目的</th></tr></thead><tbody><tr><td>累积 <strong>10 条</strong>才 flush</td><td>避免频繁写盘卡主线程</td></tr><tr><td><code>OnApplicationQuit</code> 补刷</td><td>保住最后几条（往往是崩溃前的关键信息）</td></tr><tr><td>超 <strong>200KB</strong> 截断，保留后半</td><td>防止文件无限膨胀</td></tr><tr><td>每次启动写<strong>分隔行</strong></td><td>能分清哪段是哪一次运行</td></tr></tbody></table><h2 id="日志级别" tabindex="-1">日志级别 <a class="header-anchor" href="#日志级别" aria-label="Permalink to &quot;日志级别&quot;">​</a></h2><p>日志分三级，在「日志」页可按级别筛选：</p><table tabindex="0"><thead><tr><th>级别</th><th>颜色</th><th>用于</th></tr></thead><tbody><tr><td><strong>信息</strong></td><td>正常</td><td>常规流程（加载了哪个 Mod、应用了什么参数）</td></tr><tr><td><strong>告警</strong></td><td>橙色</td><td>可预期的问题（Mod 重名冲突、模型回退）</td></tr><tr><td><strong>错误</strong></td><td>红色</td><td>引擎异常桥接（Unity 报错）、加载失败</td></tr></tbody></table><p>「复制全部日志」<strong>不受筛选影响</strong>——永远导出完整 200 条，方便整段诊断。</p><h2 id="引擎异常自动进日志" tabindex="-1">引擎异常自动进日志 <a class="header-anchor" href="#引擎异常自动进日志" aria-label="Permalink to &quot;引擎异常自动进日志&quot;">​</a></h2><p><code>ModLogHook.cs</code> 会接管 Unity 的 <code>Error</code> / <code>Exception</code> / <code>Assert</code> 回调，把它们自动写进日志页。</p><p><strong>异常风暴限流</strong>：如果某一帧抛出成千上万条异常，不会刷爆日志。</p><h2 id="「状态」页探针-modprobe" tabindex="-1">「状态」页探针（ModProbe） <a class="header-anchor" href="#「状态」页探针-modprobe" aria-label="Permalink to &quot;「状态」页探针（ModProbe）&quot;">​</a></h2><p>当问题不是「报错」而是「行为不对」时，看「状态」页。它每 0.5 秒读一次<strong>战斗现场</strong>：</p><ul><li>当前回合数</li><li>是否玩家回合</li><li>主炮装填门数</li><li>鱼雷装填管数</li><li>当前倍速（<code>Time.timeScale</code>）</li></ul><p>不用靠猜。</p><p>「状态」页还有一份<strong>偏离原版的参数清单</strong>——遍历全部 23 个参数，列出当前值 ≠ 默认值的项。任何时候觉得「数值怎么不对劲」，先看这里。</p><h2 id="游戏内「设备自检」" tabindex="-1">游戏内「设备自检」 <a class="header-anchor" href="#游戏内「设备自检」" aria-label="Permalink to &quot;游戏内「设备自检」&quot;">​</a></h2><p>「日志」页会把当前设备信息也写进日志：</p><ul><li>屏幕宽度 / 高度</li><li>DPI</li><li>系统版本</li><li>总内存</li><li>是否高分屏</li><li>渲染分辨率</li></ul><p>作者换机测试时一键导出，逐台累积成兼容矩阵。</p><h2 id="常用调试手段速查" tabindex="-1">常用调试手段速查 <a class="header-anchor" href="#常用调试手段速查" aria-label="Permalink to &quot;常用调试手段速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你想知道</th><th>用哪个</th></tr></thead><tbody><tr><td>加载了哪些 Mod、哪些失败了</td><td>「日志」页筛「信息 / 错误」</td></tr><tr><td>为什么我的 Mod 没生效</td><td>「日志」页 + 确认是否重开过游戏</td></tr><tr><td>数值为什么不对</td><td>「状态」页「偏离原版的参数」清单</td></tr><tr><td>某个模型为什么没加载</td><td>「Mod」页底部模型自检 + 日志</td></tr><tr><td>战斗中行为异常</td><td>「状态」页探针快照</td></tr><tr><td>游戏崩了 / 弹错误</td><td>日志页筛「错误」（引擎异常已桥接进来）</td></tr></tbody></table><h2 id="写代码时怎么打日志" tabindex="-1">写代码时怎么打日志 <a class="header-anchor" href="#写代码时怎么打日志" aria-label="Permalink to &quot;写代码时怎么打日志&quot;">​</a></h2><div class="language-csharp vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ModLog</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;加载 Mod：&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> name);              </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 信息</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ModLogWarn</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;舰级重名：&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> cls </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;，用后者覆盖&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 告警</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ModLogErr</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;模型加载失败：&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> path);        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 错误</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><div class="warning custom-block"><p class="custom-block-title">别忘了 try/catch</p><p>任何可能抛异常的地方都要包 <code>try/catch</code>，在 <code>catch</code> 里记一条错误日志然后<strong>继续执行</strong>。日志接口本身也必须是「不会抛异常」的——否则诊断工具自己成了崩溃源。</p></div><h2 id="一键预设的硬边界必须机器校验" tabindex="-1">一键预设的硬边界必须机器校验 <a class="header-anchor" href="#一键预设的硬边界必须机器校验" aria-label="Permalink to &quot;一键预设的硬边界必须机器校验&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">成组预设值是最难查的假阴性</p><p>一键预设 / 批量赋值如果超出 <code>ParamDef.HardMin/HardMax</code>，会被 <code>Clamp</code> <strong>静默钳制</strong>——实际值与标称值不符，而且<strong>不报错</strong>。</p><p>改预设之后，<strong>必须跑校验脚本逐项比对</strong>。本工程有这样一个脚本，别跳过。</p></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>回源码结构 → <a href="/AtlanticFleetSite/docs/dev/codebase">框架源码结构</a></li><li>改框架 → <a href="/AtlanticFleetSite/docs/dev/hack">如何修改框架本身</a></li><li>玩家侧排查 → <a href="/AtlanticFleetSite/docs/use/troubleshooting">出问题了怎么查</a></li></ul>`,31)])])}const g=a(d,[["render",r]]);export{k as __pageData,g as default};
